import './styles.css';
import { useState, useMemo } from 'react';

// Customer data with features
interface Customer {
  id: number;
  spending: number; // Monthly spending (0-100)
  visits: number; // Store visits per month (0-100)
  emoji: string;
  name: string;
}

// Generate sample customers
const generateCustomers = (): Customer[] => {
  const names = ['Alex', 'Sam', 'Jordan', 'Taylor', 'Morgan', 'Casey', 'Riley', 'Quinn', 'Avery', 'Peyton', 'Drew', 'Sage', 'Rowan', 'Skyler', 'Jamie', 'Finley'];
  const emojis = ['👤', '👩', '👨', '🧑', '👱', '👴', '👵', '🧔', '👲', '👳', '🧕', '👮', '👷', '💂', '🕵️', '👩‍🔬'];

  // Create distinct clusters
  const clusters = [
    // High spenders, frequent visitors (VIPs)
    { spending: [70, 100], visits: [70, 100], count: 4 },
    // Low spenders, frequent visitors (Browsers)
    { spending: [10, 35], visits: [65, 95], count: 4 },
    // High spenders, rare visitors (Big Purchasers)
    { spending: [65, 95], visits: [10, 35], count: 4 },
    // Low spenders, rare visitors (Casual)
    { spending: [10, 40], visits: [10, 40], count: 4 },
  ];

  const customers: Customer[] = [];
  let id = 0;

  clusters.forEach(cluster => {
    for (let i = 0; i < cluster.count; i++) {
      customers.push({
        id: id,
        spending: Math.round(cluster.spending[0] + Math.random() * (cluster.spending[1] - cluster.spending[0])),
        visits: Math.round(cluster.visits[0] + Math.random() * (cluster.visits[1] - cluster.visits[0])),
        emoji: emojis[id % emojis.length],
        name: names[id % names.length],
      });
      id++;
    }
  });

  return customers;
};

// Simple K-means clustering
function kMeansClustering(customers: Customer[], k: number): number[] {
  if (customers.length === 0) return [];

  // Initialize centroids randomly from existing points
  let centroids = customers
    .sort(() => Math.random() - 0.5)
    .slice(0, k)
    .map(c => ({ spending: c.spending, visits: c.visits }));

  let assignments = new Array(customers.length).fill(0);

  // Run a few iterations
  for (let iter = 0; iter < 10; iter++) {
    // Assign each customer to nearest centroid
    assignments = customers.map(customer => {
      let minDist = Infinity;
      let closest = 0;

      centroids.forEach((centroid, i) => {
        const dist = Math.sqrt(
          Math.pow(customer.spending - centroid.spending, 2) +
          Math.pow(customer.visits - centroid.visits, 2)
        );
        if (dist < minDist) {
          minDist = dist;
          closest = i;
        }
      });

      return closest;
    });

    // Update centroids
    centroids = centroids.map((_, i) => {
      const clusterCustomers = customers.filter((_, j) => assignments[j] === i);
      if (clusterCustomers.length === 0) return centroids[i];

      return {
        spending: clusterCustomers.reduce((sum, c) => sum + c.spending, 0) / clusterCustomers.length,
        visits: clusterCustomers.reduce((sum, c) => sum + c.visits, 0) / clusterCustomers.length,
      };
    });
  }

  return assignments;
}

const clusterColors = ['#ef4444', '#22c55e', '#3b82f6', '#f59e0b', '#8b5cf6'];
const clusterNames = ['Cluster A', 'Cluster B', 'Cluster C', 'Cluster D', 'Cluster E'];
const clusterDescriptions: Record<string, string> = {};

function getClusterDescription(customers: Customer[], assignments: number[], clusterIndex: number): string {
  const clusterCustomers = customers.filter((_, i) => assignments[i] === clusterIndex);
  if (clusterCustomers.length === 0) return 'Empty cluster';

  const avgSpending = clusterCustomers.reduce((sum, c) => sum + c.spending, 0) / clusterCustomers.length;
  const avgVisits = clusterCustomers.reduce((sum, c) => sum + c.visits, 0) / clusterCustomers.length;

  const spendingLevel = avgSpending > 60 ? 'High' : avgSpending > 35 ? 'Medium' : 'Low';
  const visitLevel = avgVisits > 60 ? 'Frequent' : avgVisits > 35 ? 'Occasional' : 'Rare';

  if (spendingLevel === 'High' && visitLevel === 'Frequent') return 'VIP Customers';
  if (spendingLevel === 'Low' && visitLevel === 'Frequent') return 'Window Shoppers';
  if (spendingLevel === 'High' && visitLevel === 'Rare') return 'Big Spenders';
  if (spendingLevel === 'Low' && visitLevel === 'Rare') return 'Casual Visitors';
  return `${spendingLevel} spend, ${visitLevel} visits`;
}

function ScatterPlot({ 
  customers, 
  assignments, 
  showClusters 
}: { 
  customers: Customer[]; 
  assignments: number[];
  showClusters: boolean;
}) {
  return (
    <div className="scatter-plot">
      <div className="axis-label y-axis">Visits per Month</div>
      <div className="axis-label x-axis">Monthly Spending ($)</div>

      <div className="plot-area">
        {/* Grid lines */}
        <div className="grid-lines">
          {[0, 25, 50, 75, 100].map(v => (
            <div key={`h-${v}`} className="grid-line horizontal" style={{ bottom: `${v}%` }}>
              <span className="grid-label">{v}</span>
            </div>
          ))}
          {[0, 25, 50, 75, 100].map(v => (
            <div key={`v-${v}`} className="grid-line vertical" style={{ left: `${v}%` }}>
              <span className="grid-label">{v}</span>
            </div>
          ))}
        </div>

        {/* Data points */}
        {customers.map((customer, i) => (
          <div
            key={customer.id}
            className="data-point"
            style={{
              left: `${customer.spending}%`,
              bottom: `${customer.visits}%`,
              backgroundColor: showClusters ? clusterColors[assignments[i]] : '#6b7280',
              borderColor: showClusters ? clusterColors[assignments[i]] : '#6b7280',
            }}
            title={`${customer.name}: $${customer.spending} spending, ${customer.visits} visits`}
          >
            <span className="point-emoji">{customer.emoji}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

function ClusterLegend({ 
  customers, 
  assignments, 
  numClusters 
}: { 
  customers: Customer[]; 
  assignments: number[];
  numClusters: number;
}) {
  return (
    <div className="cluster-legend">
      <h3>Discovered Segments</h3>
      <div className="legend-items">
        {Array.from({ length: numClusters }).map((_, i) => {
          const count = assignments.filter(a => a === i).length;
          const description = getClusterDescription(customers, assignments, i);

          return (
            <div key={i} className="legend-item">
              <div 
                className="legend-color" 
                style={{ backgroundColor: clusterColors[i] }}
              />
              <div className="legend-info">
                <strong>{description}</strong>
                <span className="legend-count">{count} customers</span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function CustomerList({ 
  customers, 
  assignments, 
  showClusters 
}: { 
  customers: Customer[]; 
  assignments: number[];
  showClusters: boolean;
}) {
  return (
    <div className="customer-list">
      <h3>Customer Data</h3>
      <div className="list-header">
        <span>Customer</span>
        <span>Spending</span>
        <span>Visits</span>
        {showClusters && <span>Segment</span>}
      </div>
      <div className="list-items">
        {customers.map((customer, i) => (
          <div 
            key={customer.id} 
            className="list-item"
            style={{
              borderLeftColor: showClusters ? clusterColors[assignments[i]] : 'transparent'
            }}
          >
            <span className="customer-name">
              {customer.emoji} {customer.name}
            </span>
            <span>${customer.spending}</span>
            <span>{customer.visits}/mo</span>
            {showClusters && (
              <span 
                className="segment-badge"
                style={{ backgroundColor: clusterColors[assignments[i]] }}
              >
                {getClusterDescription(customers, assignments, assignments[i])}
              </span>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

export default function App() {
  const [customers] = useState(generateCustomers);
  const [numClusters, setNumClusters] = useState(4);
  const [showClusters, setShowClusters] = useState(false);

  const assignments = useMemo(() => {
    return kMeansClustering(customers, numClusters);
  }, [customers, numClusters]);

  return (
    <div className="app">
      <div className="header">
        <h1>Clustering Explorer</h1>
        <p className="subtitle">
          Watch unsupervised learning find natural groups in customer data — without being told what to look for!
        </p>
      </div>

      <div className="main-content">
        <div className="visualization-panel">
          <ScatterPlot 
            customers={customers} 
            assignments={assignments}
            showClusters={showClusters}
          />

          <div className="controls">
            <div className="control-group">
              <label>Number of clusters: {numClusters}</label>
              <input
                type="range"
                min="2"
                max="5"
                value={numClusters}
                onChange={(e) => setNumClusters(parseInt(e.target.value))}
                disabled={!showClusters}
              />
            </div>

            <button 
              className={`cluster-btn ${showClusters ? 'active' : ''}`}
              onClick={() => setShowClusters(!showClusters)}
            >
              {showClusters ? 'Hide Clusters' : 'Find Clusters!'}
            </button>
          </div>

          {showClusters && (
            <ClusterLegend 
              customers={customers}
              assignments={assignments}
              numClusters={numClusters}
            />
          )}
        </div>

        <div className="data-panel">
          <CustomerList 
            customers={customers}
            assignments={assignments}
            showClusters={showClusters}
          />
        </div>
      </div>

      <div className="insight-box">
        <h3>What's Happening?</h3>
        <p>
          This is <strong>unsupervised learning</strong> in action! The algorithm looks at customer data
          (spending and visit frequency) and automatically groups similar customers together.
        </p>
        <p>
          <strong>Key insight:</strong> Nobody told the algorithm what a "VIP" or "Window Shopper" is.
          It discovered these segments by finding patterns in the data. This is how businesses discover
          customer segments they didn't even know existed!
        </p>
        <p>
          <strong>Try it:</strong> Change the number of clusters and see how the groupings change.
          More clusters = more specific segments. Fewer clusters = broader groupings.
        </p>
      </div>
    </div>
  );
}

